## Task
Write a rule based on a clearly DIFFERENT idea from all rules above, likely to score higher.

response:
The rule instead biases toward **resource efficiency**: it estimates each type’s unproductive overhead from travel, charging and maintenance, ignores the genome’s default type for default openings, and chooses the new type with the lowest overhead per work hour (with end-of-horizon fit/overshoot handling). For available robots it first avoids starting a second maintenance while one is active, then balances a normalized load combining duty counts and duty hours, with a small efficiency bonus so longer/cleaner duty types are used when loads are similar.

```python
def rule(ctx):
    def get_info(k):
        if k is None or k < 0 or k >= len(ctx.types):
            return None
        return ctx.types[k]

    max_maint = 0.0
    max_duty = 0.0
    max_work = 0.0
    for info in ctx.types:
        if info is not None:
            if info["maintenance_time"] > max_maint:
                max_maint = info["maintenance_time"]
            if info["work_time"] > max_duty:
                max_duty = info["work_time"]
            if info["continue_max_work"] > max_work:
                max_work = info["continue_max_work"]

    active = False
    active_until = -1e100
    for r in ctx.robots:
        info = get_info(r.type)
        if info is None:
            continue
        if r.ready > ctx.t:
            thresh = (info["charge_time"] + info["work_time"] +
                      info["out_travel_time"] + info["return_travel_time"] + 1.0)
            if r.ready - ctx.t > thresh:
                active = True
                if r.ready > active_until:
                    active_until = r.ready

    cap_ok = False
    if ctx.capacity >= ctx.remaining - 1e-9:
        cap_ok = True

    sum_duty = 0.0
    n_robots = 0
    for r in ctx.robots:
        info = get_info(r.type)
        if info is not None:
            sum_duty += info["work_time"]
            n_robots += 1
    if n_robots > 0:
        avg_duty = sum_duty / n_robots
    else:
        sd = 0.0
        nt = 0
        for info in ctx.types:
            if info is not None:
                sd += info["work_time"]
                nt += 1
        avg_duty = sd / nt if nt > 0 else 10.0
    if avg_duty <= 1e-9:
        avg_duty = 10.0

    def new_actions():
        cand = []
        for k, info in enumerate(ctx.types):
            if info is not None and ctx.left[k] > 0:
                work = info["work_time"]
                if ctx.remaining <= 0:
                    fit = 0
                    overshoot = 0.0
                else:
                    if work <= ctx.remaining + 1e-9:
                        fit = 0
                        overshoot = 0.0
                    else:
                        fit = 1
                        overshoot = work - ctx.remaining

                overhead = (info["out_travel_time"] + info["return_travel_time"] +
                            info["charge_time"]) / max(work, 1e-9)
                cmax = info["continue_max_work"]
                maint = info["maintenance_time"]
                maint_overhead = maint / max(cmax, 1e-9)
                cost = overhead + maint_overhead

                rem_pen = 0.0
                if ctx.remaining > 0 and work > 1e-9 and ctx.remaining < 4.0 * work:
                    rem = ctx.remaining % work
                    rem_pen = min(rem, work - rem) / work

                gene = 0 if k == ctx.gene_type else 1
                cand.append((fit, overshoot, cost, rem_pen, -work, gene, k))

        if not cand:
            return [("new", ctx.gene_type)]
        cand.sort()
        return [("new", item[-1]) for item in cand]

    new_list = new_actions()
    if not ctx.available:
        return new_list

    end_mode = ctx.remaining < max(max_maint, max_work) + 2.0 * max_duty

    items = []
    for r in ctx.available:
        info = get_info(r.type)
        if info is None:
            items.append((None, False, False, 0.0, 0.0, 0, r))
            continue

        work = info["work_time"]
        will = r.duties_left <= 1
        lead = (info["out_travel_time"] + work +
                info["return_travel_time"] + 1.0)
        safe_start = (not active) or (active_until <= ctx.t + lead + 1e-9)

        balance = r.count + r.hours / avg_duty

        cycle = (info["out_travel_time"] + work +
                 info["return_travel_time"] + info["charge_time"])
        if cycle <= 1e-9:
            cycle = work + 1.0
        duty_frac = work / cycle
        cmax = info["continue_max_work"]
        maint = info["maintenance_time"]
        uptime = cmax / (cmax + maint) if cmax + maint > 1e-9 else 0.0
        eff = 0.5 * duty_frac + 0.5 * uptime

        near_pen = 0
        if active and cap_ok and r.duties_left <= 2:
            near_pen = 1

        items.append((info, will, safe_start, balance, eff, near_pen, r))

    def make_key(item):
        info, will, safe_start, balance, eff, near_pen, r = item
        if info is None:
            return (9, 0, 0, 0, r.idx)

        work = info["work_time"]

        if end_mode:
            if ctx.remaining <= work + 1e-9:
                return (0, 0, balance, -eff, r.idx)
            if will and active and not safe_start and cap_ok:
                return (2, -balance, -eff, r.idx)
            if will:
                return (1, -balance, -eff, r.idx)
            return (0, near_pen, balance, -eff, r.idx)

        if will and (not active or safe_start):
            return (0, 0, -balance, -eff, r.idx)
        if will and active and not safe_start:
            return (2, -balance, -eff, r.idx)
        return (1, near_pen, balance, -eff, r.idx)

    keyed = [(make_key(item), item[-1]) for item in items]
    keyed.sort(key=lambda x: x[0])
    ordered = [r for key, r in keyed]

    actions = [("reuse", r) for r in ordered]
    actions.extend(new_list)
    return actions
