        new_cand.sort()
        new_list = [("new", item[-1]) for item in new_cand]
    else:
        new_list = [("new", ctx.gene_type)]

    if not ctx.available:
        return new_list

    cap = ctx.capacity
    rem = max(ctx.remaining, 1e-9)
    ratio = cap / (rem * 1.25)
    pressure = 0.0 if ratio >= 1.0 else (1.0 - ratio)

    if n_types <= 1:
        beta = 0.0
    elif all_same_work:
        beta = 7.0 + 4.0 * pressure
    else:
        beta = 2.0 + 4.0 * pressure

    first_sum = 0.0
    first_n = 0
    for r in ctx.robots:
        if r.first_maint is not None:
            first_sum += r.first_maint
            first_n += 1
    first_mean = first_sum / first_n if first_n > 0 else None

    def common_score(r, use_urgency):
        info = get_info(r.type)
        if info is None:
            return 1e12

        work = info["work_time"]
        delta = 1.0 + work / avg_work
        load = r.count + r.hours / avg_work
        s = 2.0 * load * delta + delta * delta

        due = r.duties_left <= 1
        remaining = ctx.remaining
        maint = info["maintenance_time"]
        finish = ctx.t + work + info["return_travel_time"] + maint

        if use_urgency and n_types > 1:
