                if not can_finish:
                    if remaining > work + maint:
                        s += 45.0
                    else:
                        s += 10.0
                else:
                    s -= 6.0

        if (use_urgency and n_types > 1 and r.duties_left == 2 and
                not active and remaining > maint + 3.0 * work):
            s -= 0.5 + 1.5 * pressure

        if end_mode:
            if due and remaining > work + 1e-9:
                if remaining < maint + work:
                    s += 30.0
                else:
                    s += 1.0
            if active and due:
                s += 12.0

        if late_mode and remaining > 0:
            if work > remaining + 1e-9:
                s += 20.0 + 4.0 * (work - remaining)
            else:
                s -= 1.5 * (work / max(max_duty, 1e-9))

        if r.first_maint is None and due and first_n > 0:
            projected = ctx.t + work + info["return_travel_time"]
            s += abs(projected - first_mean) / max(ctx.T, 1.0) * 12.0

        return s + 1e-6 * r.idx

    primary = sorted(ctx.available, key=lambda r: common_score(r, True))
    secondary = sorted(ctx.available, key=lambda r: common_score(r, False))

    ordered = []
    used = set()
    n = len(primary)
    for i in range(n):
        r = primary[i]
        if r.idx not in used:
            ordered.append(r)
            used.add(r.idx)
        r = secondary[i]
        if r.idx not in used:
            ordered.append(r)
            used.add(r.idx)

    for r in ctx.available:
        if r.idx not in used:
            ordered.append(r)
            used.add(r.idx)

    actions = [("reuse", r) for r in ordered]
    actions.extend(new_list)
    return actions
