response:
The rule uses capacity-aware maintenance pressure: it delays triggering new maintenance when capacity is tight or too few robots remain immediately available, but uses maintenance-eligible robots early when capacity slack is sufficient to avoid future clustering. It also consolidates new robots onto already-opened types (especially for equal-duty groups) and uses a near-horizon “can this robot actually finish the remaining duties without maintenance?” test to avoid late unnecessary maintenance.

```python
def rule(ctx):
    def get_info(k):
        if k is None or k < 0 or k >= len(ctx.types):
            return None
        return ctx.types[k]

    max_maint = 0.0
    max_duty = 0.0
    max_work = 0.0
    min_duty = None
    max_duty_val = 0.0
    n_types = 0
    sum_type_w = 0.0

    for info in ctx.types:
        if info is not None:
            n_types += 1
            if info["maintenance_time"] > max_maint:
                max_maint = info["maintenance_time"]
            w = info["work_time"]
            if w > max_duty:
                max_duty = w
            if info["continue_max_work"] > max_work:
                max_work = info["continue_max_work"]
            sum_type_w += w
            if min_duty is None:
                min_duty = w
                max_duty_val = w
            else:
                if w < min_duty:
                    min_duty = w
                if w > max_duty_val:
                    max_duty_val = w

    same_duty = (min_duty is not None and max_duty_val - min_duty <= 1e-9)
    avg_type_w = sum_type_w / n_types if n_types > 0 else 10.0
    if avg_type_w <= 1e-9:
        avg_type_w = 10.0

    opened_of_type = [0] * len(ctx.types)
    sum_opened_w = 0.0
    n_opened = 0
    for r in ctx.robots:
        info = get_info(r.type)
        if info is not None:
            if 0 <= r.type < len(opened_of_type):
                opened_of_type[r.type] += 1
            sum_opened_w += info["work_time"]
            n_opened += 1

    avg_duty = sum_opened_w / n_opened if n_opened > 0 else avg_type_w
    if avg_duty <= 1e-9:
        avg_duty = 10.0

    active_maint = 0
    for r in ctx.robots:
        info = get_info(r.type)
        if info is not None and r.ready > ctx.t:
            thr = (info["charge_time"] + info["work_time"] +
                   info["out_travel_time"] + info["return_travel_time"] + 1.0)
            if r.ready - ctx.t > thr:
                active_maint += 1

    cap_ok = ctx.capacity >= ctx.remaining - 1e-9
    avail_n = len(ctx.available)
    risky = (active_maint > 0 and
             (not cap_ok or active_maint >= max(1, avail_n - 1)))

    end_mode = ctx.remaining < max(max_maint, max_work) + 2.0 * max_duty

    def new_actions():
        cand = []
        if same_duty and n_types > 1:
            for k, info in enumerate(ctx.types):
                if info is not None and ctx.left[k] > 0:
                    w = info["work_time"]
                    if w <= 0:
                        w = 1e-9
                    if ctx.remaining <= 0 or w <= ctx.remaining + 1e-9:
                        fit = 0
                        overshoot = 0.0
                    else:
                        fit = 1
                        overshoot = w - ctx.remaining

                    single = info["single_work_time"]
                    if single <= 0:
                        single = w
                    dpm = info["continue_max_work"] / single
                    if dpm < 1e-9:
                        dpm = 1e-9

                    cycle = (info["work_time"] + info["out_travel_time"] +
                             info["return_travel_time"] + info["charge_time"])
                    if cycle <= 1e-9:
                        cycle = w + 1.0

                    cost = cycle + info["maintenance_time"] / dpm
                    novel = 0.0 if opened_of_type[k] > 0 else 0.5
                    gene = 0 if k == ctx.gene_type else 1
                    cand.append((fit, overshoot, cost + novel,
                                 info["maintenance_time"], -dpm, -w, gene, k))
        else:
            for k, info in enumerate(ctx.types):
                if info is not None and ctx.left[k] > 0:
                    w = info["work_time"]
                    if ctx.remaining <= 0 or w <= ctx.remaining + 1e-9:
                        fit = 0
                    else:
                        fit = 1
                    gene = 0 if k == ctx.gene_type else 1
                    single = info["single_work_time"]
                    if single <= 0:
                        single = 1.0
                    dpm = info["continue_max_work"] / single
                    cand.append((fit, gene, -dpm,
                                 info["maintenance_time"], -w, k))

        if not cand:
            return [("new", ctx.gene_type)]
        cand.sort()
        return [("new", item[-1]) for item in cand]

    def make_key(r):
        info = get_info(r.type)
        if info is None:
            return (9, 0, 0, 0, 0, r.idx)

        w = info["work_time"]
        if w <= 0:
            w = 1e-9
        load = r.count + r.hours / avg_duty
        will = r.duties_left <= 1

        if end_mode:
            if ctx.remaining <= w + 1e-9:
                return (0, 0, load, -r.duties_left, r.hours, r.idx)

            if will:
                rank = 3 if active_maint > 0 else 2
                return (rank, -load, -r.duties_left, r.hours, 0, r.idx)

            need = int(math.ceil(ctx.remaining / w - 1e-9))
            if need < 1:
                need = 1
            safe_rank = 0 if r.duties_left >= need else 1
            if risky and r.duties_left <= 2:
                safe_rank = 2
            return (1, safe_rank, load, -r.duties_left, -r.budget, r.idx)

        if will:
            if risky:
                return (3, -load, -r.duties_left, r.hours, 0, r.idx)
            return (0, -load, -r.duties_left, r.hours, 0, r.idx)

        if risky and r.duties_left <= 2:
            return (2, load, -r.duties_left, -r.budget, 0, r.idx)

        return (1, load, -r.duties_left, -r.budget, r.hours, r.idx)

    ordered = sorted(ctx.available, key=make_key)
    actions = [("reuse", r) for r in ordered]
    actions.extend(new_actions())
    return actions
