def rule(ctx):
    def get_info(k):
        if k is None or k < 0 or k >= len(ctx.types):
            return None
        return ctx.types[k]

    max_maint = 0.0
    max_duty = 0.0
    max_work = 0.0
    n_types = 0
    min_duty = None
    max_duty_val = 0.0
    for info in ctx.types:
        if info is not None:
            n_types += 1
            if info["maintenance_time"] > max_maint:
                max_maint = info["maintenance_time"]
            if info["work_time"] > max_duty:
                max_duty = info["work_time"]
            if info["continue_max_work"] > max_work:
                max_work = info["continue_max_work"]
            w = info["work_time"]
            if min_duty is None:
                min_duty = w
                max_duty_val = w
            else:
                if w < min_duty:
                    min_duty = w
                if w > max_duty_val:
                    max_duty_val = w

    same_duty = True
    if min_duty is not None and max_duty_val - min_duty > 1e-9:
        same_duty = False

    active = False
    for r in ctx.robots:
        if r.ready > ctx.t:
            info = get_info(r.type)
            if info is not None:
                thresh = (info["charge_time"] + info["work_time"] +
                          info["out_travel_time"] + info["return_travel_time"] + 1.0)
                if r.ready - ctx.t > thresh:
                    active = True
                    break

    def old_new_actions():
        cand = []
        for k, info in enumerate(ctx.types):
            if info is not None and ctx.left[k] > 0:
                work = info["work_time"]
                fit = 0 if ctx.remaining <= 0 or work <= ctx.remaining + 1e-9 else 1
                gene = 0 if k == ctx.gene_type else 1
                single = info["single_work_time"]
                if single <= 0:
                    single = 1.0
                dpm = info["continue_max_work"] / single
                cand.append((fit, gene, -dpm, info["maintenance_time"], -work, k))
        if not cand:
            return [("new", ctx.gene_type)]
        cand.sort()
        return [("new", item[-1]) for item in cand]

    def efficient_new_actions_h():
        cand = []
        for k, info in enumerate(ctx.types):
            if info is not None and ctx.left[k] > 0:
                work = info["work_time"]
                if work <= 0:
                    work = 1e-9
                single = info["single_work_time"]
                if single <= 0:
                    single = 1e-9
                dpm = info["continue_max_work"] / single
                if dpm < 1e-9:
                    dpm = 1e-9
                cycle = (work + info["out_travel_time"] +
                         info["return_travel_time"] + info["charge_time"])
                fit = 0 if ctx.remaining <= 0 or work <= ctx.remaining + 1e-9 else 1
                rem_after = ctx.remaining - work
                if rem_after <= 1e-9:
                    cost = cycle
                else:
                    budget_left = info["continue_max_work"] - single
                    if rem_after <= budget_left + 1e-9:
                        cost = cycle
