## Task
Write a rule based on a clearly DIFFERENT idea from all rules above, likely to score higher.

response:
The key idea is to adapt the reuse policy to whether maintenance can be avoided: compute the total duty hours still available from the current robot budgets (excluding any robots already in long maintenance). If this capacity is enough to cover the remaining horizon, balance duty hours and counts across robots and strongly avoid triggering any maintenance (including deprioritizing robots with only one duty left). Otherwise, deliberately stagger maintenance by prioritising robots closest to their budget limit, and break ties in favour of robots that have not yet had their first maintenance to improve first-maintenance balance. When some robot is already in maintenance, always prefer healthy, high-budget robots to avoid overlapping maintenance and ensure continuous coverage. This differs from both existing rules, which use fixed sort policies regardless of whether maintenance is actually necessary.

```python
def rule(ctx):
    def get_info(k):
        if k is None or k < 0 or k >= len(ctx.types):
            return None
        return ctx.types[k]

    max_maint = 0.0
    max_duty = 0.0
    max_work = 0.0
    for info in ctx.types:
        if info is not None:
            if info["maintenance_time"] > max_maint:
                max_maint = info["maintenance_time"]
            if info["work_time"] > max_duty:
                max_duty = info["work_time"]
            if info["continue_max_work"] > max_work:
                max_work = info["continue_max_work"]

    active = False
    for r in ctx.robots:
        if r.ready > ctx.t:
            info = get_info(r.type)
            if info is not None:
                thresh = (info["charge_time"] + info["work_time"] +
                          info["out_travel_time"] + info["return_travel_time"] + 1.0)
                if r.ready - ctx.t > thresh:
                    active = True
                    break

    def new_actions():
        cand = []
        for k, info in enumerate(ctx.types):
            if info is not None and ctx.left[k] > 0:
                work = info["work_time"]
                fit = 0 if ctx.remaining <= 0 or work <= ctx.remaining + 1e-9 else 1
                gene = 0 if k == ctx.gene_type else 1
                single = info["single_work_time"]
                if single <= 0:
                    single = 1.0
                dpm = info["continue_max_work"] / single
                cand.append((fit, gene, -dpm, info["maintenance_time"], -work, k))
        if not cand:
            return [("new", ctx.gene_type)]
        cand.sort()
        return [("new", item[-1]) for item in cand]

    new_list = new_actions()
    if not ctx.available:
        return new_list

    # Total duty hours available from current budgets without any new maintenance
    total_current_duty = 0.0
    for r in ctx.robots:
        info = get_info(r.type)
        if info is None:
            continue
        single = info["single_work_time"]
        if single > 0:
            duties = r.budget / single
            total_current_duty += duties * info["work_time"]

    if active:
        mode = "active"
    else:
        avoid_maint = (total_current_duty >= ctx.remaining * 1.01)
        mode = "balance" if avoid_maint else "stagger"

    def sort_key(r):
        info = get_info(r.type)
        if info is None:
            return (9, r.count, r.idx)

        due = r.budget
        will = r.duties_left <= 1

        if mode == "active":
            return (0 if not will else 1, -due, r.count, r.hours, r.idx)

        if mode == "balance":
            return (0 if not will else 1, r.hours, r.count, -due, r.idx)

        # stagger
        return (due, 0 if r.first_maint is None else 1, r.count, r.hours, r.idx)

    ordered = sorted(ctx.available, key=sort_key)
    actions = [("reuse", r) for r in ordered]
    actions.extend(new_list)
    return actions
