response:
The main change targets group H: when all robot types share the same duty length (so duty counts are directly comparable), the rule now uses a balanced count-first order similar to the default and to the successful single-type case, instead of the budget-first order that was causing count imbalance. For mixed duty lengths (group M) it keeps the budget-aware order. Additionally, the fallback new-robot type choice now prioritises expected coverage efficiency (cycle time and maintenance amortisation) over the genome’s `gene_type`, using the gene only as a late tie-breaker; this reduces unnecessary resource opening when the rule itself has to repair.

```python
def rule(ctx):
    def get_info(k):
        if k is None or k < 0 or k >= len(ctx.types):
            return None
        return ctx.types[k]

    max_maint = 0.0
    max_duty = 0.0
    max_work = 0.0
    min_duty = 1e9
    n_types = 0
    for info in ctx.types:
        if info is not None:
            n_types += 1
            if info["maintenance_time"] > max_maint:
                max_maint = info["maintenance_time"]
            if info["work_time"] > max_duty:
                max_duty = info["work_time"]
            if info["work_time"] < min_duty:
                min_duty = info["work_time"]
            if info["continue_max_work"] > max_work:
                max_work = info["continue_max_work"]

    uniform_duty = (n_types <= 1) or (max_duty - min_duty < 1e-9)

    active = False
    for r in ctx.robots:
        if r.ready > ctx.t:
            info = get_info(r.type)
            if info is not None:
                thresh = (info["charge_time"] + info["work_time"] +
                          info["out_travel_time"] + info["return_travel_time"] + 1.0)
                if r.ready - ctx.t > thresh:
                    active = True
                    break

    def new_actions():
        cand = []
        for k, info in enumerate(ctx.types):
            if info is not None and ctx.left[k] > 0:
                work = info["work_time"]
                fit = 0 if ctx.remaining <= 0 or work <= ctx.remaining + 1e-9 else 1
                single = info["single_work_time"]
                if single <= 0:
                    single = 1.0
                dpm = info["continue_max_work"] / single
                cycle = work + info["out_travel_time"] + info["return_travel_time"] + info["charge_time"]
                if ctx.remaining < info["continue_max_work"]:
                    cost = cycle / max(work, 1e-9)
                else:
                    cost = cycle / max(work, 1e-9) + info["maintenance_time"] / max(dpm * work, 1e-9)
                gene = 0 if k == ctx.gene_type else 1
                cand.append((fit, cost, -dpm, info["maintenance_time"], -work, gene, k))
        if not cand:
            return [("new", ctx.gene_type)]
        cand.sort()
        return [("new", item[-1]) for item in cand]

    new_list = new_actions()
    if not ctx.available:
        return new_list

    end_mode = ctx.remaining < max(max_maint, max_work) + 2.0 * max_duty

    def sort_key(r):
        info = get_info(r.type)
        if info is None:
            return (9, r.count, r.idx)

        duty = info["work_time"]
        maint = info["maintenance_time"]
        due = r.budget
        will = r.duties_left <= 1
        safe_will = will and ctx.remaining <= duty + 1e-9

        if end_mode:
            if will and not safe_will:
                if active:
                    return (2, -r.count, r.hours, maint, r.idx)
                return (1, -r.count, r.hours, maint, r.idx)

            if safe_will:
                safe_rank = 0
            else:
                if ctx.remaining <= duty + 1e-9:
                    safe_rank = 0
                else:
                    safe_rank = 0 if r.duties_left > 2 else 1
            return (0, safe_rank, r.count, -r.duties_left, r.hours, r.idx)

        if active:
            if will:
                return (1, -r.count, maint, -due, r.idx)
            safe_rank = 0 if r.duties_left > 2 else 1
            return (0, safe_rank, r.count, -r.duties_left, -due, r.hours, r.idx)

        if will:
            return (0, -r.count, r.hours, maint, due, r.idx)

        if uniform_duty:
            return (1, r.count, -r.duties_left, r.hours, due, r.idx)

        return (1, r.budget, r.count, r.hours, r.idx)

    ordered = sorted(ctx.available, key=sort_key)
    actions = [("reuse", r) for r in ordered]
    actions.extend(new_list)
    return actions
