response:
The rule uses a capacity-aware maintenance-pressure heuristic: when capacity is safe, it staggers maintenance by giving a bonus to robots close to maintenance while still prioritizing balanced count/hour load; when capacity is tight, it reverses this and avoids triggering maintenance, preferring robots with more budget left. New robot types are ranked by fit to the remaining horizon and effective unproductive overhead per productive duty hour, so forced openings remain resource-efficient.

```python
def rule(ctx):
    def get_info(k):
        if k is None or k < 0 or k >= len(ctx.types):
            return None
        return ctx.types[k]

    n_types = 0
    max_maint = 0.0
    max_duty = 0.0
    max_work = 0.0
    min_duty = None
    max_duty_val = 0.0
    sum_type_w = 0.0

    for info in ctx.types:
        if info is not None:
            n_types += 1
            w = info["work_time"]
            if info["maintenance_time"] > max_maint:
                max_maint = info["maintenance_time"]
            if w > max_duty:
                max_duty = w
            if info["continue_max_work"] > max_work:
                max_work = info["continue_max_work"]
            sum_type_w += w
            if min_duty is None:
                min_duty = w
                max_duty_val = w
            else:
                if w < min_duty:
                    min_duty = w
                if w > max_duty_val:
                    max_duty_val = w

    if min_duty is None:
        min_duty = 10.0
    if max_duty <= 1e-9:
        max_duty = 10.0
    avg_type_w = sum_type_w / n_types if n_types > 0 else 10.0
    if avg_type_w <= 1e-9:
        avg_type_w = 10.0

    opened_of_type = [0] * len(ctx.types)
    sum_opened_w = 0.0
    n_opened = 0
    for r in ctx.robots:
        info = get_info(r.type)
        if info is not None:
            if 0 <= r.type < len(opened_of_type):
                opened_of_type[r.type] += 1
            sum_opened_w += info["work_time"]
            n_opened += 1

    avg_duty = sum_opened_w / n_opened if n_opened > 0 else avg_type_w
    if avg_duty <= 1e-9:
        avg_duty = 10.0

    active_maint = 0
    for r in ctx.robots:
        info = get_info(r.type)
        if info is not None and r.ready > ctx.t + 1e-9:
            thr = (info["charge_time"] + info["work_time"] +
                   info["out_travel_time"] + info["return_travel_time"] + 1.0)
            if r.ready - ctx.t > thr:
                active_maint += 1

    cap_ok = ctx.capacity >= ctx.remaining - 1e-9
    tight = (not cap_ok) or (active_maint > 0 and len(ctx.available) <= active_maint + 1)
    if not tight:
        slack = ctx.capacity - ctx.remaining
        if slack < 0.25 * max_duty:
            tight = True

    def new_actions():
        cand = []
        R = ctx.remaining
        for k, info in enumerate(ctx.types):
            if info is None or ctx.left[k] <= 0:
                continue

            duty = info["work_time"]
            if duty <= 1e-9:
                duty = 1e-9

            single = info["single_work_time"]
            if single <= 1e-9:
                single = duty

            dpm = info["continue_max_work"] / single
            if dpm < 1e-9:
                dpm = 1e-9

            cycle = duty + info["out_travel_time"] + info["return_travel_time"] + info["charge_time"]
            maint_per_duty = info["maintenance_time"] / dpm
            overhead_per_hour = (cycle - duty + maint_per_duty) / duty

            if R <= 1e-9 or duty <= R + 1e-9:
                fit = 0
                overshoot = 0.0
            else:
                fit = 1
                overshoot = (duty - R) / duty

            leftover_pen = 0.0
            if R > duty + 1e-9 and min_duty is not None:
                rem2 = R - duty
                if rem2 < min_duty - 1e-9:
                    leftover_pen = (min_duty - rem2) / min_duty

            novel = 0.0 if opened_of_type[k] > 0 else 0.3
            gene = 0 if k == ctx.gene_type else 1

            key = (fit, overshoot, overhead_per_hour + leftover_pen + novel,
                   info["maintenance_time"], -dpm, -duty, gene, k)
            cand.append((key, k))

        if not cand:
            return [("new", ctx.gene_type)]
        cand.sort()
        return [("new", item[1]) for item in cand]

    def reuse_key(r):
        info = get_info(r.type)
        if info is None:
            return (9, r.count, r.idx)

        duty = info["work_time"]
        if duty <= 1e-9:
            duty = 1e-9

        load = r.count + r.hours / avg_duty
        urgent = r.duties_left <= 1
        soon = r.duties_left <= 2
        type_tie = (info["out_travel_time"] + info["return_travel_time"] +
                    info["charge_time"]) / duty

        fit_pen = 0.0
        if ctx.remaining > 1e-9:
            if duty > ctx.remaining + 1e-9:
                fit_pen = (duty - ctx.remaining) / duty
            else:
                rem2 = ctx.remaining - duty
                if rem2 > 1e-9 and rem2 < min_duty - 1e-9:
                    fit_pen = (min_duty - rem2) / min_duty

        if ctx.remaining <= duty + 1e-9:
            first_pen = 1 if (urgent and r.first_maint is None) else 0
            return (0, first_pen, load, fit_pen, -r.duties_left, type_tie, r.idx)

        if tight:
            rank = 0 if r.duties_left > 1 else 1
            return (rank, -r.duties_left, load, fit_pen, -r.budget, type_tie, r.idx)

        if urgent:
            bonus = 2.5
        elif soon:
            bonus = 1.0
        else:
            bonus = 0.0

        return (load - bonus, r.duties_left, fit_pen, -r.budget, type_tie, r.idx)

    new_list = new_actions()
    if not ctx.available:
        return new_list

    ordered = sorted(ctx.available, key=reuse_key)
    actions = [("reuse", r) for r in ordered]
    actions.extend(new_list)
    return actions
