                return (0, -bucket, bal, -b, r.idx)
            else:
                return (1, mt, -bucket, bal, -b, r.idx)
        else:
            return (bucket, bal, b, r.idx)

    def alt_key(item):
        if near_end:
            return near_end_key(item)
        r, w, mt, will, safe_fin, maint_comp, can_fin, bal, b = item
        return (bal, b, r.idx)

    items_sorted = sorted(items, key=primary_key)
    default_item = items_sorted[0]
    rest = items_sorted[1:]
    rest_sorted = sorted(rest, key=alt_key)
    ordered = [default_item] + rest_sorted

    actions = [("reuse", item[0]) for item in ordered]
    actions.extend(new_actions())
    return actions
