            if w <= 0:
                w = 1e-9
            single = info["single_work_time"]
            if single <= 0:
                single = w
            dpm = info["continue_max_work"] / single
            if dpm < 1e-9:
                dpm = 1e-9

            cycle = w + info["out_travel_time"] + info["return_travel_time"] + info["charge_time"]
            if cycle <= 1e-9:
