        return_gap = w + out + ret + mt + charge
        maint_comp = remaining > return_gap + 1e-9
        can_fin = (r.duties_left * w) >= remaining - 1e-9

        bal = ((r.count - mean_count) / scale_count +
               (r.hours + w - mean_hours) / scale_hours)
        load = r.count + r.hours / avg_duty

        budget = r.budget
        if budget is None:
            budget = r.duties_left * w

        items.append((r, w, mt, will, safe_fin, maint_comp, can_fin,
                      bal, load, budget, dpm))

    def key_hom(item):
        r, w, mt, will, safe_fin, maint_comp, can_fin, bal, load, budget, dpm = item

        if near_end:
            if safe_fin:
                overshoot = w - remaining
                if overshoot < 0.0:
                    overshoot = 0.0
                return (0, overshoot, bal, r.idx)
            if (not will) and can_fin:
                return (1, bal, -r.duties_left, r.idx)
            if not will:
                return (2, bal, -r.duties_left, r.idx)
            if maint_comp:
                return (3, -bal, r.duties_left, mt, r.idx)
            return (4, -bal, r.duties_left, mt, r.idx)

