def rule(ctx):
    def get_info(k):
        if k is None or k < 0 or k >= len(ctx.types):
            return None
        return ctx.types[k]

    max_maint = 0.0
    max_duty = 0.0
    max_work = 0.0
    min_duty = None
    max_duty_val = 0.0
    n_types = 0
    sum_type_w = 0.0
    for info in ctx.types:
        if info is not None:
            n_types += 1
