Improve this rule. Its weakest group is M. Use the diagnostics to decide what to change (e.g. too many resources in the no-deviation roster vs. too little room for useful deviations).

response:
The main change targets group M: new-robot openings no longer prioritize the genome’s arbitrary type early; instead they prefer efficient type economics and reuse already-opened types. For mixed duty lengths, reuse ordering now balances projected load more explicitly and provides better non-default alternatives, while leaving the strong E/H logic largely intact.

```python
def rule(ctx):
    def get_info(k):
        if k is None or k < 0 or k >= len(ctx.types):
            return None
        return ctx.types[k]

    n_types = 0
    sum_type_w = 0.0
    max_maint = 0.0
    max_duty = 0.0
    max_work = 0.0
    min_duty = None
    max_duty_val = 0.0

    for info in ctx.types:
        if info is not None:
            n_types += 1
            w = info["work_time"]
            if info["maintenance_time"] > max_maint:
                max_maint = info["maintenance_time"]
            if w > max_duty:
                max_duty = w
            if info["continue_max_work"] > max_work:
                max_work = info["continue_max_work"]
            sum_type_w += w
            if min_duty is None:
                min_duty = w
                max_duty_val = w
            else:
                if w < min_duty:
                    min_duty = w
                if w > max_duty_val:
                    max_duty_val = w

    if min_duty is None:
        min_duty = 0.0
    same_duty = (max_duty_val - min_duty <= 1e-9)
    mixed = not same_duty

    avg_type_w = sum_type_w / n_types if n_types > 0 else 10.0
    if avg_type_w <= 1e-9:
        avg_type_w = 10.0

    opened_of_type = [0] * len(ctx.types)
    n_opened = 0
    sum_count = 0.0
    sum_hours = 0.0
    sum_count2 = 0.0
    sum_hours2 = 0.0
    sum_opened_w = 0.0
    active_maint = 0

    for r in ctx.robots:
        n_opened += 1
        c = r.count
        h = r.hours
        sum_count += c
        sum_hours += h
        sum_count2 += c * c
        sum_hours2 += h * h

        info = get_info(r.type)
        if info is not None:
            if 0 <= r.type < len(opened_of_type):
                opened_of_type[r.type] += 1
            sum_opened_w += info["work_time"]
            if r.ready > ctx.t:
                thr = (info["charge_time"] + info["work_time"] +
                       info["out_travel_time"] + info["return_travel_time"] + 1.0)
                if r.ready - ctx.t > thr:
                    active_maint += 1

    if n_opened > 0:
        mean_count = sum_count / n_opened
        mean_hours = sum_hours / n_opened
        var_count = sum_count2 / n_opened - mean_count * mean_count
        var_hours = sum_hours2 / n_opened - mean_hours * mean_hours
        if var_count < 0.0:
            var_count = 0.0
        if var_hours < 0.0:
            var_hours = 0.0
        scale_count = var_count ** 0.5
        if scale_count < 1.0:
            scale_count = 1.0
        scale_hours = var_hours ** 0.5
        if scale_hours < avg_type_w:
            scale_hours = avg_type_w
        if scale_hours < 1e-9:
            scale_hours = 10.0
    else:
        mean_count = 0.0
        mean_hours = 0.0
        scale_count = 1.0
        scale_hours = avg_type_w

    avg_duty = sum_opened_w / n_opened if n_opened > 0 else avg_type_w
    if avg_duty <= 1e-9:
        avg_duty = 10.0

    remaining = ctx.remaining
    near_end = remaining < max(max_maint, max_work) + 2.0 * max_duty

    cap_ok = ctx.capacity >= remaining - 1e-9
    avail_n = len(ctx.available)
    half = n_opened // 2
    if half < 1:
        half = 1
    congested = active_maint > 0 and ((not cap_ok) or active_maint >= half)
    avoid_maint = congested or (not cap_ok) or (active_maint > 0 and avail_n <= active_maint + 1)

    def new_actions():
        cand = []
        for k, info in enumerate(ctx.types):
            if info is None or ctx.left[k] <= 0:
                continue

            w = info["work_time"]
            if w <= 0:
                w = 1e-9
            single = info["single_work_time"]
            if single <= 0:
                single = w
            dpm = info["continue_max_work"] / single
            if dpm < 1e-9:
                dpm = 1e-9

            cycle = w + info["out_travel_time"] + info["return_travel_time"] + info["charge_time"]
            if cycle <= 1e-9:
                cycle = w + 1.0
            cost_rate = (cycle + info["maintenance_time"] / dpm) / w
            gene_rank = 0 if k == ctx.gene_type else 1
            opened_pen = 0.0 if opened_of_type[k] > 0 else 0.45

            if near_end:
                if w <= remaining + 1e-9:
                    fit = 0
                    n = int(remaining // w)
                    if n * w < remaining - 1e-9:
                        n += 1
                    if n < 1:
                        n = 1
                    extra = n * w - remaining
                else:
                    fit = 1
                    n = 1
                    extra = w - remaining
                key = (fit, n, extra, opened_pen, cost_rate,
                       info["maintenance_time"], -dpm, -w, gene_rank, k)
            else:
                if w <= remaining + 1e-9:
                    fit = 0
                    overshoot = 0.0
                else:
                    fit = 1
                    overshoot = w - remaining

                key = (fit, overshoot, cost_rate + opened_pen,
                       info["maintenance_time"], -dpm, -w, gene_rank, k)

            cand.append((key, k))

        if not cand:
            return [("new", ctx.gene_type)]
        cand.sort(key=lambda x: x[0])
        return [("new", item[1]) for item in cand]

    if not ctx.available:
        return new_actions()

    items = []
    for r in ctx.available:
        info = get_info(r.type)
        if info is None:
            w = 10.0
            out = 0.0
            ret = 0.0
            charge = 0.0
            mt = 0.0
            dpm = 1.0
        else:
            w = info["work_time"]
            if w <= 0:
                w = 1e-9
            out = info["out_travel_time"]
            ret = info["return_travel_time"]
            charge = info["charge_time"]
            mt = info["maintenance_time"]
            single = info["single_work_time"]
            if single <= 0:
                single = w
            dpm = info["continue_max_work"] / single
            if dpm < 1e-9:
                dpm = 1e-9

        will = r.duties_left <= 1
        safe_fin = remaining <= w + 1e-9
        return_gap = w + out + ret + mt + charge
        maint_comp = remaining > return_gap + 1e-9
        can_fin = (r.duties_left * w) >= remaining - 1e-9

        bal = ((r.count - mean_count) / scale_count +
               (r.hours + w - mean_hours) / scale_hours)
        load = r.count + r.hours / avg_duty

        budget = r.budget
        if budget is None:
            budget = r.duties_left * w

        items.append((r, w, mt, will, safe_fin, maint_comp, can_fin,
                      bal, load, budget, dpm))

    def key_hom(item):
        r, w, mt, will, safe_fin, maint_comp, can_fin, bal, load, budget, dpm = item

        if near_end:
            if safe_fin:
                overshoot = w - remaining
                if overshoot < 0.0:
                    overshoot = 0.0
                return (0, overshoot, bal, r.idx)
            if (not will) and can_fin:
                return (1, bal, -r.duties_left, r.idx)
            if not will:
                return (2, bal, -r.duties_left, r.idx)
            if maint_comp:
                return (3, -bal, r.duties_left, mt, r.idx)
            return (4, -bal, r.duties_left, mt, r.idx)

        if n_types == 1:
            if congested:
                if not will:
                    return (0, -r.duties_left, bal, budget, r.idx)
                return (1, -bal, r.duties_left, r.idx)
            else:
                if will:
                    return (0, -bal, r.duties_left, budget, r.idx)
                return (1, r.duties_left, budget, bal, r.idx)
        else:
            if congested:
                if not will:
                    return (0, bal, -r.duties_left, budget, r.idx)
                return (1, -bal, r.duties_left, r.idx)
            else:
                if will:
                    return (0, -bal, r.duties_left, budget, r.idx)
                return (1, bal, r.duties_left, budget, r.idx)

    def key_mix(item):
        r, w, mt, will, safe_fin, maint_comp, can_fin, bal, load, budget, dpm = item

        if near_end:
            if remaining <= w + 1e-9:
                overshoot = w - remaining
                if overshoot < 0.0:
                    overshoot = 0.0
                exact_rank = 0 if overshoot <= 1e-9 else 1
                return (0, exact_rank, overshoot, bal, r.idx)
            if (not will) and can_fin:
                return (1, bal, -r.duties_left, -w, r.idx)
            if not will:
                return (2, bal, -r.duties_left, -w, r.idx)
            if maint_comp:
                return (3, -bal, r.duties_left, mt, r.idx)
            return (4, -bal, r.duties_left, mt, r.idx)

        if avoid_maint:
            if not will:
                safe_rank = 0 if r.duties_left > 2 else 1
                return (0, safe_rank, load, -r.duties_left, budget, -w, r.idx)
            return (1, -load, -r.count, r.duties_left, r.idx)
        else:
            if will:
                return (0, bal, r.duties_left, budget, -w, r.idx)
            return (1, bal, r.duties_left, budget, -w, r.idx)

    if same_duty:
        items.sort(key=key_hom)
    else:
        items.sort(key=key_mix)

    actions = [("reuse", item[0]) for item in items]
    actions.extend(new_actions())
    return actions
